import Foundation
import SkyCore

/// Where the land is, as one bit per half-degree cell.
///
/// 720×360 cells in 32,400 bytes — every coastline on Earth in less space than
/// a small photograph, which is why the globe needs no imagery at all.
/// Regenerated by `Tools/generate-land-mask.py` from Natural Earth.
public enum LandMask {
    public static let width = 720
    public static let height = 360

    static let bits: [UInt8] = {
        guard let url = Bundle.module.url(forResource: Resource.name, withExtension: Resource.extension),
              let data = try? Data(contentsOf: url), data.count == width * height / 8 else {
            assertionFailure("land-mask.bin is missing or the wrong size")
            return []
        }
        return [UInt8](data)
    }()

    public static func isLand(latitude: Double, longitude: Double) -> Bool {
        guard !bits.isEmpty else { return false }

        var column = Int((longitude + 180) / 360 * Double(width))
        var row = Int((90 - latitude) / 180 * Double(height))
        column = min(max(column, 0), width - 1)
        row = min(max(row, 0), height - 1)

        let offset = row * width + column
        return (bits[offset >> 3] >> (7 - UInt8(offset & 7))) & 1 == 1
    }

    public static func isLand(_ coordinate: Coordinate) -> Bool {
        isLand(latitude: coordinate.latitude, longitude: coordinate.longitude)
    }
}

extension LandMask {
    enum Resource {
        static let name = "land-mask"
        static let `extension` = "bin"
    }
}
